#!/usr/bin/env node
// Final means the selected dist already contains every approved after value.
// No overlays, candidate modes, project-module imports, or environment overrides.
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
const D=path.dirname(fileURLToPath(import.meta.url)),arg=process.argv.indexOf('--dist');assert.ok(arg>=0&&process.argv[arg+1],'Pass --dist /absolute/path/to/dist');assert.equal(process.argv.length,4,'Only --dist is supported');const dist=path.resolve(process.argv[arg+1]),read=n=>JSON.parse(fs.readFileSync(path.join(D,n),'utf8')),sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const pkg=read('records.json'),app=read('append-manifest.json'),base=read('identity-baseline.json'),mapping=read('preservation-map.json'),variants=read('variant-map.json'),sections=read('sections.json'),archive=read('archive-extension-proposal.json');const E=new Map();
for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(f=>f.endsWith('.json')))for(const e of JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f))).entries){assert.ok(!E.has(e.id),'duplicate '+e.id);E.set(e.id,e);}
const checks=[];function check(name,fn){try{checks.push({name,status:'passed',...fn()});}catch(e){checks.push({name,status:'failed',error:e.stack||String(e)});}}
const target=key=>{const [eid,q]=key.split('#'),e=E.get(eid);assert.ok(e,key);const it=e.items.find((x,i)=>String(x.id??i)===q);assert.ok(it,key);return it;};const leaf=(e,p)=>p.reduce((v,k)=>v[k],e);const plain=s=>s.replace(/<[^>]*>/g,'').replaceAll('&gt;','>').replaceAll('&lt;','<').replaceAll('&amp;','&');
const blocks=s=>[...s.matchAll(/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g)];
function balanced(s){const stack=[],voids=new Set(['br','hr','img','input','meta','link','wbr']);for(const m of s.matchAll(/<(\/?)([A-Za-z][\w-]*)\b[^>]*>/g)){const tag=m[2].toLowerCase();if(m[1])assert.equal(stack.pop(),tag);else if(!voids.has(tag)&&!m[0].endsWith('/>'))stack.push(tag);}assert.deepEqual(stack,[]);}
check('four-exact-applied-leaves-and-two-compiled-appends',()=>{assert.equal(pkg.records.length,4);for(const r of pkg.records){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.equal(leaf(E.get(r.entryId),r.path),r.after,'Not applied '+r.stableReviewKey+' '+r.path.at(-1));}assert.equal(app.additions.length,2);for(const a of app.additions){assert.equal(a.expectedOldCount,2);assert.equal(E.get(a.entryId).items[a.expectedIndex].id,a.questionId);assert.deepEqual(E.get(a.entryId).items[a.expectedIndex],a.expectedItem);assert.equal(sha(a.expectedItem.a),a.afterSha256);}return{appliedLeaves:4,compiledAppends:2,stagedInMemory:0,siteWrites:0};});
check('immutable-question-identities-and-complete-serving-prefix',()=>{const mb=base.entries.find(e=>e.id==='ai-模型与评测-3'),m=E.get(mb.id);assert.equal(m.items.length,mb.items.length);for(let i=0;i<mb.items.length;i++)assert.deepEqual(Object.fromEntries(Object.entries(m.items[i]).filter(([k])=>!['a','lead'].includes(k))),Object.fromEntries(Object.entries(mb.items[i]).filter(([k])=>!['a','lead'].includes(k))));const sb=base.entries.find(e=>e.id==='own-theory-serving'),s=E.get(sb.id);assert.deepEqual(s.items.slice(0,2),sb.items);assert.equal(s.items.length,4);return{originalModelQuestions:9,completeServingPrefix:2,appendIndexes:[2,3]};});
check('all-193-source-blocks-have-substantive-destinations',()=>{assert.equal(mapping.blocks.length,193);for(const idx of [6,7]){const old=base.entries.find(e=>e.id==='ai-模型与评测-3').items[idx].a,bs=blocks(old),rows=mapping.blocks.filter(b=>b.sourceKey==='ai-模型与评测-3#'+idx);assert.equal(bs.length,rows.length);for(const [n,b] of rows.entries()){assert.equal(b.index,n);assert.equal(b.html,bs[n][0]);assert.equal(sha(b.html),b.sha256);assert.equal(Array.from(old).slice(...b.sourceSpanCodePoints).join(''),b.html);assert.ok(b.destinations.length);for(const d of b.destinations){assert.equal(sha(d.html),d.sha256);assert.ok(/<p\b/.test(d.html),'Title-only destination');for(const f of d.fragments||[d.html])assert.ok(target(d.stableReviewKey).a.includes(f),'Missing destination '+b.sourceKey+':'+n+' → '+d.section);}}}return{mappedBlocks:193,mixedArchivedSourceBlocks:3};});
check('all-23-variants-and-old-anchors-retained',()=>{assert.equal(variants.variants.length,23);let anchors=0;for(const idx of [6,7]){const b=base.entries.find(e=>e.id==='ai-模型与评测-3').items[idx],a=target('ai-模型与评测-3#'+idx).a;for(const m of b.a.matchAll(/\bid="([^"]+)"/g)){assert.ok(a.includes('id="'+m[1]+'"'));anchors++;}const detail=a.match(/<details class="qa-variants">[\s\S]*?<\/details>/)?.[0];assert.ok(detail);const count=[...detail.matchAll(/<li>/g)].length;assert.equal(count,idx===6?11:12);for(const v of variants.variants.filter(v=>v.sourceKey.endsWith('#'+idx))){assert.ok(plain(detail).includes(v.originalText));for(const d of v.destinations)for(const f of d.fragments||[d.html])assert.ok(target(d.stableReviewKey).a.includes(f));}}return{variants:23,anchors};});
check('canonical-fragments-remain-real-body-evidence',()=>{let fragments=0;for(const s of Object.values(sections).filter(s=>s.readOnly)){assert.equal(sha(s.html),s.sha256);for(const f of s.fragments){assert.ok(target(s.stableReviewKey).a.includes(f),s.stableReviewKey+' '+s.section);assert.ok(plain(f).length>30);fragments++;}}return{readOnlySections:Object.values(sections).filter(s=>s.readOnly).length,fragments};});
check('single-existing-robot-archive-preserves-and-extends-original',()=>{const f=path.join(dist,archive.distRelativePath),a=fs.readFileSync(f,'utf8');assert.equal(a,archive.after,'Archive extension not applied');assert.equal(sha(a),archive.afterSha256);assert.equal(sha(archive.before),archive.beforeSha256);const at=archive.insertionOffsetCodePoints;assert.equal(a,Array.from(archive.before).slice(0,at).join('')+archive.insertedHtml+Array.from(archive.before).slice(at).join(''));const old=base.entries.find(e=>e.id==='ai-模型与评测-3').items[7].a;const b=blocks(old)[24][0];assert.ok(a.includes(b),'Complete original VLA mixed paragraph missing');assert.ok(!target('own-theory-serving#q-model-edge-acceptance').a.includes('动作安全控制与急停由独立受控组件保证'),'Control specialty leaked into main answer');return{sharedArchiveFiles:1,completeOriginalVlaBlock:true,oldArchiveBytesPreserved:true};});
check('unique-mechanisms-and-corrected-boundaries-present',()=>{const a=target('ai-模型与评测-3#6').a,b=target('ai-模型与评测-3#7').a,r=target('own-theory-serving#q-model-runtime-lifecycle').a,e=target('own-theory-serving#q-model-edge-acceptance').a;for(const t of ['2/7','5/7','no_sync','2(P−1)X/P','(P−1)X/P','acc/l','Expert Choice','不能叫跨机器零拷贝','不能在完成前覆盖或释放','不同 step'])assert.ok(a.includes(t),t);for(const t of ['q=clip(round(x/s)+z)','BF16','NF4','GGUF','QAT','QLoRA','动态与静态','并不证明模型已经用整数算子运行','稠密运算仍在','二值化','prefill时间减半'])assert.ok(b.includes(t),t);for(const t of ['release 返回 Promise','在途请求','external/RSS','校准集','引擎制品'])assert.ok(r.includes(t),t);for(const t of ['三十五亿字节','遥测','医疗器械','急停','控制频率']){if(t==='急停')assert.ok(!e.includes(t));else assert.ok(e.includes(t),t);}return{parallelAndQuantizationBoundaries:true,runtimeAndEdgeBoundaries:true};});
check('html-balanced-and-every-route-resolves',()=>{let links=0;const answers=[...pkg.records.map(r=>r.after),...app.additions.map(a=>target(a.entryId+'#'+a.questionId).a)];for(const s of answers){balanced(s);assert.ok(!/<pre\b|<code\b/.test(s),'Theory answers must not accumulate code');for(const m of s.matchAll(/href="#\/e\/([^"]+)"/g)){const [eid,q]=decodeURIComponent(m[1]).split('/');assert.ok(E.has(eid),'missing entry '+eid);if(q!==undefined)assert.ok(E.get(eid).items.some((it,i)=>String(it.id??i)===q),'missing item '+m[1]);links++;}for(const m of s.matchAll(/href="(assets\/[^"#]+)(?:#[^"]*)?"/g))assert.ok(fs.existsSync(path.join(dist,m[1])),'missing archive route');}return{links};});
check('small-cpu-algebra-fixtures-not-gpu-performance',()=>{const g1=[2,4],g2=[1,3,5,7,9],mean=x=>x.reduce((s,v)=>s+v,0)/x.length;assert.notEqual((mean(g1)+mean(g2))/2,mean([...g1,...g2]));assert.equal((2*mean(g1)+5*mean(g2))/7,mean([...g1,...g2]));const X=[2,-3,5],W=[[1,2],[4,-1],[2,3]],full=[0,1].map(j=>X.reduce((s,x,i)=>s+x*W[i][j],0)),row=[0,1].map(j=>X[0]*W[0][j]+X.slice(1).reduce((s,x,i)=>s+x*W[i+1][j],0));assert.deepEqual(row,full);assert.notEqual(Math.max(0,-2+1),Math.max(0,-2)+Math.max(0,1));let maxError=0;for(let n=2;n<=12;n++){const logits=Array.from({length:n},(_,i)=>Math.sin(i*3.7+n)*30),vals=logits.map((_,i)=>Math.cos(i)),M=Math.max(...logits),den=logits.reduce((s,x)=>s+Math.exp(x-M),0),ref=logits.reduce((s,x,i)=>s+Math.exp(x-M)*vals[i],0)/den;let m=-Infinity,l=0,acc=0;for(let k=0;k<n;k+=3){const z=logits.slice(k,k+3),nm=Math.max(m,...z),fac=Math.exp(m-nm);l=l*fac+z.reduce((s,x)=>s+Math.exp(x-nm),0);acc=acc*fac+z.reduce((s,x,j)=>s+Math.exp(x-nm)*vals[k+j],0);m=nm;}maxError=Math.max(maxError,Math.abs(acc/l-ref));}assert.ok(maxError<1e-12);for(const P of [2,4,8]){const X=64;assert.equal((P-1)*X/P*2,2*(P-1)*X/P);}const q=(x,s,min,max)=>Math.min(max,Math.max(min,Math.round(x/s))),s=.25;for(const x of [-1.1,-.6,.1,.9,1.4])assert.ok(Math.abs(s*q(x,s,-8,7)-x)<=s/2+1e-12);assert.equal(7e9*4/8,3.5e9);return{weightedGradientCounterexample:true,tpLinearAlgebra:true,nonlinearityCounterexample:true,onlineSoftmaxCases:11,maxAbsoluteError:maxError,quantizationRoundingBound:true,scope:'CPU arithmetic only; no CUDA/NCCL concurrency, GPU benchmark or model quality claim.'};});
const out={schemaVersion:1,mode:'final-dist-only',dist,testedAt:new Date().toISOString(),node:process.version,checks,passed:checks.filter(c=>c.status==='passed').length,failed:checks.filter(c=>c.status==='failed').length,stagedInMemory:0,siteWrites:0,limitations:['No full-site build, historical chain, browser rendering, live runtime, GPU experiment, model task benchmark, or robotics safety validation.']};console.log(JSON.stringify(out,null,2));if(out.failed)process.exitCode=1;
